using System.Collections.Generic;public class Solution{List<string>o=new();void F(string s,int p,int part,List<string>v){if(part==4){if(p==s.Length)o.Add(string.Join(".",v));return;}for(int l=1;l<=3&&p+l<=s.Length;l++){if(l>1&&s[p]=='0')break;string x=s.Substring(p,l);if(int.Parse(x)>255)break;v.Add(x);F(s,p+l,part+1,v);v.RemoveAt(v.Count-1);}}public IList<string> RestoreIpAddresses(string s){F(s,0,0,new List<string>());return o;}}
